custom_css:
/* ============================================
   F.A.Y.E. O.S. 𝜗ৎ
============================================ */

@import url("https://fonts.googleapis.com/css2?family=Pixelify+Sans:wght@400;500;600;700&family=VT323&display=swap");

:root {
  --bunny-pink:        #6a2040;
  --bunny-pink-dark:   #b05070;
  --bunny-rose:        #7a2040;
  --bunny-blush:       #150810;
  --bunny-cream:       #2e1422;
  --bunny-muted:       #7a3050;
  --bunny-text:        #fce8f0;
  --bunny-text-light:  #d4a0b8;
  --bunny-border:      #8a3050;
  --bunny-win-title:   #ffffff;
  --bunny-win-bg:      #2a1020;
  --pixel-border:      2px solid var(--bunny-border);
  scrollbar-color: var(--bunny-pink-dark) var(--bunny-blush);
}

/* =====================
   GLOBAL TYPOGRAPHY
   ===================== */
body, .mes_text, p, input, textarea, select,
button:not([class*="fa-"]):not([class*="fa "]),
span:not([class*="fa-"]):not([class*="fa "]),
div:not([class*="fa-"]):not([class*="fa "]) {
  font-family: 'Pixelify Sans', monospace !important;
  color: var(--bunny-text);
}

.mes_text {
  font-family: 'Pixelify Sans', monospace !important;
  font-size: 14px;
  line-height: 1.7;
  color: var(--bunny-text) !important;
  text-shadow: none !important;
}

h1, h2, h3, h4, h5, h6,
.standoutHeader,
.ch_name .name_text,
.timestamp,
.mesIDDisplay,
.tokenCounterDisplay,
.mes_timer {
  font-family: 'VT323', monospace !important;
  color: var(--bunny-rose) !important;
  text-shadow: 1px 1px 0 var(--bunny-blush) !important;
  letter-spacing: 1.5px;
}

/* =====================
   GLOBAL BACKGROUND
   ===================== */
body {
  background-color: var(--bunny-blush) !important;
}

#chat::before {
  content: '';
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background-image: radial-gradient(circle, rgba(122, 32, 64, 0.15) 1px, transparent 1px);
  background-size: 8px 8px;
  pointer-events: none;
  z-index: 0;
}


/* =====================
   TOP BAR
   ===================== */

#top-bar {
  background: linear-gradient(to right, #7a2040 0%, #b05070 50%, #7a2040 100%) !important;
  border-bottom: 3px solid var(--bunny-rose) !important;
  box-shadow: 0 3px 0 rgba(100, 20, 50, 0.3) !important;
}

.drawer-icon::before{
  color: var(--bunny-text) !important;
  text-shadow: none !important;
}

#ai-config-button .drawer-icon::before          { content: "AI" !important; font-family: 'VT323', monospace !important; font-weight: normal !important; font-size: 13px !important;  }
#sys-settings-button .drawer-icon::before       { content: "SYS" !important; font-family: 'VT323', monospace !important; font-weight: normal !important; font-size: 13px !important; }
#advanced-formatting-button .drawer-icon::before{ content: "FMT" !important; font-family: 'VT323', monospace !important; font-weight: normal !important; font-size: 13px !important; }
#WI-SP-button .drawer-icon::before              { content: "WLD" !important; font-family: 'VT323', monospace !important; font-weight: normal !important; font-size: 13px !important; }
#user-settings-button .drawer-icon::before      { content: "USR" !important; font-family: 'VT323', monospace !important; font-weight: normal !important; font-size: 13px !important; }
#backgrounds-button .drawer-icon::before        { content: "BG" !important;  font-family: 'VT323', monospace !important; font-weight: normal !important; font-size: 13px !important; }
#extensions-settings-button .drawer-icon::before{ content: "EXT" !important; font-family: 'VT323', monospace !important; font-weight: normal !important; font-size: 13px !important; }
#persona-management-button .drawer-icon::before { content: "ME" !important;  font-family: 'VT323', monospace !important; font-weight: normal !important; font-size: 13px !important; }
#rightNavHolder .drawer-icon::before {
  content: "CHR" !important;
  font-family: 'VT323', monospace !important; font-weight: normal !important; font-size: 13px !important; position: relative !important;
  top: 1.4px !important; /* Pushes the text down slightly */}

/* =====================
   CHAT MESSAGES
   ===================== */

#chat {
  padding: 8px 12px !important;
  border: none !important;
  margin: 0 !important;
  background-color: rgba(21, 8, 16, 0.6) !important;
}

.mes {
  display: flex !important;
  flex-direction: column !important;
  align-items: stretch !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin-bottom: 24px !important;
  position: relative !important;
}

.mes::after {
  display: none !important;
  content: none !important;
}

/* Character Window */
.mes .mesAvatarWrapper {
  display: flex !important;
  flex-direction: row !important;
  position: relative !important;
  width: 100% !important;
  max-width: 460px !important;
  min-height: 152px !important;
  height: auto !important;
  padding: 26px 6px 6px 6px !important;
  margin: 0 0 -2px 4px !important;
  align-self: flex-start !important;
  background: var(--bunny-cream) !important;
  border: 2px solid var(--bunny-rose) !important;
  border-radius: 0 !important;
  box-shadow: 3px 3px 0 var(--bunny-border) !important;
  gap: 6px !important;
  box-sizing: border-box !important;
  z-index: 10 !important;
  overflow: visible !important;
  bottom: auto !important;
  left: auto !important;
  right: auto !important;
  top: auto !important;
}

/* User Window */
.mes[is_user="true"] .mesAvatarWrapper {
  flex-direction: row-reverse !important;
  align-self: flex-end !important;
  margin: 0 4px -2px 0 !important;
  box-shadow: -3px 3px 0 var(--bunny-border) !important;
}

/* Window Title */
.mes .mesAvatarWrapper::before {
   content: "𝜗ৎ  profile.exe" !important;
  position: absolute !important;
  top: 0 !important; left: 0 !important; right: 0 !important;
  height: 22px !important; line-height: 20px !important;
  background: linear-gradient(to right, #7a2040 0%, #b05070 50%, #7a2040 100%) !important;
  color: #f2c4d0 !important;
  font-family: 'VT323', monospace !important; font-size: 13px !important;
  padding: 1px 8px !important;
  text-shadow: 1px 1px 0 rgba(0, 0, 0, 0.5) !important;
  border-bottom: 2px solid var(--bunny-rose) !important;
  letter-spacing: 0 !important;
  white-space: nowrap !important; overflow: hidden !important;
  display: block !important; box-sizing: border-box !important;
  z-index: 2 !important;
  box-shadow: inset 0 1px 0 rgba(21, 8, 16, 0.5) !important;
}
.mes[is_user="true"] .mesAvatarWrapper::before {
  content: "𝜗ৎ  user.exe" !important;
  background: linear-gradient(to right, #7a2040 0%, #6a2040 50%, #7a2040 100%) !important;
}

/* Avatar */
.mes .mesAvatarWrapper .avatar {
  position: static !important;
  flex: 0 0 auto !important;
  width: 134px !important;
  height: 134px !important;
  min-width: 134px !important;
  max-width: 134px !important;
  border: 2px solid var(--bunny-rose) !important;
  border-radius: 0 !important;
  overflow: hidden !important;
  background-color: var(--bunny-blush) !important;
  box-shadow: 2px 2px 0 var(--bunny-border) !important;
  margin: 0 !important;
  padding: 0 !important;
  top: auto !important;
  left: auto !important;
  right: auto !important;
  bottom: auto !important;
  display: block !important;
}

/* Avatar Image */
.mes .mesAvatarWrapper .avatar img,
.mes .mesAvatarWrapper > img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  object-position: top center !important;
  border-radius: 0 !important;
  display: block !important;
  image-rendering: auto !important;
}

/* Dialog Pop-Up */
.mes .mesAvatarWrapper::after {
  content: "> loading char.bmp\A> status: online \25CF\A> mood: wicked (>ω<)\A> hp: \2665 \2665 \2665 \2665 \2665\A> ready to chat \2665" !important;
  position: static !important;
  flex: 1 1 auto !important;
  min-width: 0 !important;
  height: 134px !important;
  white-space: pre !important;
  padding: 8px 10px !important;
  font-family: 'VT323', monospace !important;
  font-size: 14px !important;
  line-height: 18px !important;
  color: var(--bunny-text) !important;
  background: var(--bunny-cream) !important;
  border: 2px solid var(--bunny-rose) !important;
  border-radius: 0 !important;
  box-shadow: 2px 2px 0 var(--bunny-border), inset 1px 1px 0 rgba(21, 8, 16, 0.5) !important;
  overflow: hidden !important;
  letter-spacing: 0.3px !important;
  box-sizing: border-box !important;
  top: auto !important;
  left: auto !important;
  right: auto !important;
  bottom: auto !important;
  display: block !important;
  width: auto !important;
}

.mes[is_user="true"] .mesAvatarWrapper::after {
  content: "> loading user.bmp\A> status: active \25CF\A> mood: sinful (✦w✦)\A> hp: \2661 \2661 \2661 \2661 \2661\A> ready to chat \2661" !important;
  background: #150810 !important;
}

/* Message Body */
.mes .mes_block {
  flex: 1 1 auto !important;
  min-width: 0 !important;
  width: 100% !important;
  margin-left: 0 !important;
  position: relative !important;
  display: flex !important;
  flex-direction: column !important;
}

.mes .mes_block::before {
  content: '' !important;
  display: block !important;
  height: 5px !important;
  background: linear-gradient(to right, #b05070, #6a2040, #b05070) !important;
  border: 2px solid var(--bunny-rose) !important;
  border-bottom: none !important;
}

.mes[is_user="true"] .mes_block::before {
  background: linear-gradient(to right, #7a2040, #6a2040, #7a2040) !important;
}

.mes .ch_name {
  background-color: var(--bunny-pink) !important;
  border: 2px solid var(--bunny-rose) !important;
  border-top: none !important;
  border-bottom: 2px solid var(--bunny-muted) !important;
  padding: 2px 8px !important;
  border-radius: 0 !important;
  font-family: 'VT323', monospace !important;
  font-size: 15px !important;
  display: flex !important;
  align-items: center !important;
  gap: 6px !important;
  color: var(--bunny-text) !important;
}

.mes .ch_name::after {
  content: "_ [] X" !important;
  margin-left: auto !important;
  font-size: 10px !important;
  letter-spacing: 1px !important;
  color: var(--bunny-rose) !important;
  font-family: 'VT323', monospace !important;
  opacity: 0.8 !important;
  white-space: nowrap !important;
  flex-shrink: 0 !important;
}

.mes .name_text {
  font-family: 'VT323', monospace !important;
  font-size: 15px !important;
  color: var(--bunny-text) !important;
  text-shadow: none !important;
}

.mes .mes_text {
  background-color: var(--bunny-cream) !important;
  border: 2px solid var(--bunny-rose) !important;
  border-top: none !important;
  padding: 10px 14px 12px !important;
  background-image: repeating-linear-gradient(
    to bottom,
    transparent,
    transparent 22px,
    rgba(122, 32, 64, 0.2) 22px,
    rgba(122, 32, 64, 0.2) 23px
  ) !important;
  background-position: 0 30px !important;
  min-height: 40px !important;
  color: var(--bunny-text) !important;
}

.mes[is_user="true"] .ch_name {
  background-color: var(--bunny-muted) !important;
}

.mes[is_user="true"] .mes_text {
  background-color: #150810 !important;
  background-image: repeating-linear-gradient(
    to bottom,
    transparent,
    transparent 22px,
    rgba(122, 32, 64, 0.2) 22px,
    rgba(122, 32, 64, 0.2) 23px
  ) !important;
}

/* =====================
   MARKDOWN INSIDE MESSAGES
   ===================== */
.mes_text em {
  color: #e08090 !important;
  font-style: italic;
  text-shadow: none !important;
}

.mes_text strong {
  color: var(--bunny-win-title) !important;
  text-shadow: none !important;
}

.mes_text code {
  font-family: 'VT323', monospace !important;
  background-color: #1e0c16 !important;
  border: 1px solid var(--bunny-border) !important;
  color: var(--bunny-text) !important;
  padding: 1px 6px;
  border-radius: 0 !important;
  font-size: 15px;
  box-shadow: 1px 1px 0 var(--bunny-border);
}

.mes_text blockquote {
  border-left: 4px solid var(--bunny-pink-dark) !important;
  background: #1e0c16 !important;
  padding: 6px 12px !important;
  margin: 6px 0 !important;
  font-style: italic;
  color: var(--bunny-text-light) !important;
}

.mes_text p {
  text-shadow: none !important;
}

/* =====================
   TIMESTAMP / META
   ===================== */
.mes .timestamp,
.mes .tokenCounterDisplay,
.mes .mesIDDisplay,
.mes_timer {
  font-family: 'VT323', monospace !important;
  color: var(--bunny-rose) !important;
  opacity: 0.75;
  text-shadow: none !important;
  box-shadow: none !important;
  font-size: 12px !important;
}

/* =====================
   SWIPE
   ===================== */
.fa-chevron-right::before {
  display: inline !important;
  opacity: 1 !important;
  content: "⏭" !important; }
.fa-chevron-left::before {
  display: inline !important;
  opacity: 1 !important;
  content: "⏮" !important; }

.swipes-counter {
  font-family: 'VT323', monospace !important;
  color: var(--bunny-text-light) !important;
  font-size: 13px !important;
}

/* =====================
   SCROLLBARS
   ===================== */
::-webkit-scrollbar {
  width: 12px;
  height: 12px;
  background: var(--bunny-blush);
}

::-webkit-scrollbar-thumb {
  background: var(--bunny-pink-dark);
  border: 2px solid var(--bunny-rose);
  border-radius: 0 !important;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--bunny-rose);
}

::-webkit-scrollbar-track {
  background: var(--bunny-blush);
  border: 1px solid var(--bunny-muted);
}

::-webkit-scrollbar-corner {
  background: var(--bunny-blush);
}

/* =====================
   WINDOWS-STYLE DRAWER HEADERS
   ===================== */
.inline-drawer-toggle.inline-drawer-header,
.standoutHeader.inline-drawer-header,
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header {
  font-family: 'VT323', monospace !important;
  font-size: 15px;
  letter-spacing: 1px;
  text-transform: uppercase;
  background: linear-gradient(to right, #7a2040 0%, #b05070 50%, #7a2040 100%) !important;
  color: #f2c4d0 !important;
  border: 2px solid var(--bunny-rose) !important;
  border-radius: 0 !important;
  padding: 4px 8px !important;
  box-shadow:
    inset -1px -1px 0 rgba(0, 0, 0, 0.5),
    inset 1px 1px 0 rgba(21, 8, 16, 0.7) !important;
  text-shadow: 1px 1px 0 rgba(0, 0, 0, 0.6) !important;
  gap: 8px;
}

.inline-drawer-toggle.inline-drawer-header::after {
  content: "_ [] X";
  float: right;
  font-size: 9px;
  opacity: 0.85;
  letter-spacing: 1px;
  color: #221018;
  font-family: 'VT323', monospace !important;
  white-space: nowrap;
  flex-shrink: 0;
  margin-left: 6px;
  align-self: center;
}

/* =====================
   PANELS & DRAWERS
   ===================== */
.fillLeft.openDrawer,
.fillRight.openDrawer {
  background-color: var(--bunny-win-bg) !important;
  border: 2px solid var(--bunny-border) !important;
  border-radius: 0 !important;
}

.drawer-content {
  background-color: var(--bunny-win-bg) !important;
  margin-top: 0 !important;
  padding: 8px;
}

/* =====================
   POPUPS / FLOATING PANELS
   ===================== */
.popup,
.floating_panel,
#character_popup,
#options,
#floatingPrompt,
#cfgConfig,
#WorldInfo,
#SnippetsExtensionWindow {
  background-color: var(--bunny-win-bg) !important;
  border: 2px solid var(--bunny-rose) !important;
  border-radius: 0 !important;
  box-shadow: 3px 3px 0 var(--bunny-border), 5px 5px 0 rgba(100, 20, 50, 0.2) !important;
}

.popup_header,
.popup .title_bar,
.ui-dialog-titlebar {
  background: linear-gradient(to right, #7a2040 0%, #b05070 50%, #7a2040 100%) !important;
  color: #f2c4d0 !important;
  font-family: 'VT323', monospace !important;
  font-size: 16px !important;
  border-bottom: 2px solid var(--bunny-rose) !important;
  border-radius: 0 !important;
  padding: 4px 8px !important;
  box-shadow: inset 0 1px 0 rgba(21, 8, 16, 0.5) !important;
  text-shadow: 1px 1px 0 rgba(0, 0, 0, 0.6) !important;
}

.popup_close,
.ui-dialog-titlebar-close {
  background-color: #7a2040 !important;
  border: 1px solid #5a1530 !important;
  color: #221018 !important;
  border-radius: 0 !important;
  font-family: 'VT323', monospace !important;
  font-size: 14px !important;
  box-shadow: 1px 1px 0 rgba(21, 8, 16, 0.5) !important;
}

#options {
  z-index: 5000 !important;
  border: 2px solid var(--bunny-rose) !important;
  border-radius: 0 !important;
  background-color: var(--bunny-win-bg) !important;
}

#floatingPrompt, #cfgConfig, #SnippetsExtensionWindow, #WorldInfo {
  z-index: 4999 !important;
  max-width: 80vw !important;
}

/* =====================
   INPUT FIELDS
   ===================== */
select, .form-control, .ui-widget-content {
  background-color: var(--bunny-cream) !important;
  color: var(--bunny-text) !important;
  border: 2px solid var(--bunny-border) !important;
  border-radius: 0 !important;
  font-family: 'Pixelify Sans', monospace !important;
}

input[type="text"],
input[type="search"],
input[type="number"],
textarea,
.form-control,
.text_pole,
.textarea_compact {
  background-color: var(--bunny-cream) !important;
  color: var(--bunny-text) !important;
  border: 2px solid var(--bunny-border) !important;
  border-radius: 0 !important;
  font-family: 'Pixelify Sans', monospace !important;
  box-shadow: inset 1px 1px 0 rgba(122, 32, 64, 0.3) !important;
}

input:focus-visible, textarea:focus-visible, select:focus-visible {
  outline: 2px solid var(--bunny-rose) !important;
  outline-offset: 0 !important;
  border-color: var(--bunny-rose) !important;
}

.select2-container .select2-selection {
  background-color: var(--bunny-cream) !important;
  color: var(--bunny-text) !important;
  border: 2px solid var(--bunny-border) !important;
  border-radius: 0 !important;
  font-family: 'Pixelify Sans', monospace !important;
}

.select2-container .select2-selection__rendered {
  color: var(--bunny-text) !important;
  font-family: 'Pixelify Sans', monospace !important;
}

.select2-dropdown {
  background-color: var(--bunny-cream) !important;
  border: 2px solid var(--bunny-rose) !important;
  border-radius: 0 !important;
}

.select2-results__option--highlighted {
  background-color: var(--bunny-pink) !important;
  color: var(--bunny-text) !important;
}

/* =====================
   BUTTONS — Win95 pixel style
   ===================== */
.menu_button, button, .btn {
  font-family: 'Pixelify Sans', monospace !important;
  background-color: var(--bunny-pink) !important;
  color: var(--bunny-text) !important;
  border: 2px solid var(--bunny-border) !important;
  border-radius: 0 !important;
  box-shadow:
    1px 1px 0 #221018,
    2px 2px 0 var(--bunny-pink-dark) !important;
  text-shadow: none !important;
  filter: none !important;
  opacity: 1 !important;
}

.menu_button:hover, button:hover, .btn:hover {
  background-color: var(--bunny-muted) !important;
  box-shadow:
    -1px -1px 0 #221018,
    -2px -2px 0 var(--bunny-pink-dark) !important;
}

.menu_button:active, button:active {
  box-shadow: inset 1px 1px 0 var(--bunny-pink-dark) !important;
  transform: translate(1px, 1px);
}

/* =====================
   SEND FORM — PictoChat keyboard area style
   ===================== */
#form_sheld {
  padding-left: 0.5% !important;
  padding-right: 0.5% !important;
  border-top: 3px solid var(--bunny-rose) !important;
  padding-top: 4px !important;
  background-color: var(--bunny-blush) !important;
}

#nonQRFormItems {
  border: 2px solid var(--bunny-border) !important;
  border-radius: 0 !important;
  background-color: var(--bunny-cream) !important;
  box-shadow:
    inset 1px 1px 0 #221018,
    2px 2px 0 var(--bunny-border) !important;
}

#send_form {
  border: none !important;
  border-radius: 0 !important;
  max-width: 750px;
}

#send_textarea {
  background: transparent !important;
  color: var(--bunny-text) !important;
  font-family: 'Pixelify Sans', monospace !important;
  font-size: 14px;
  border: none !important;
  box-shadow: none !important;
  padding: 10px 16px !important;
}

#send_textarea::placeholder {
  font-size: 0px !important;
}

#nonQRFormItems {
  position: relative !important;
}

/* Custom Terminal Text */
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
  content: "> waiting for user input..." !important; 
  position: absolute !important;
  left: 50% !important; /* Anchors the start of the text to the exact middle */
  top: 50% !important; /* Anchors it vertically to the exact middle */
  transform: translate(-50%, -50%) !important; /* Pulls it back by half its own size to perfectly center it */
  color: var(--bunny-pink-dark) !important;
  font-family: 'VT323', monospace !important;
  font-size: 16px !important;
  opacity: 0.7 !important;
  pointer-events: none !important; 
  z-index: 10 !important;
  white-space: nowrap !important; /* Prevents the text from stacking awkwardly on tiny screens */
}

/* =====================
   SECTION HEADERS 
   ===================== */
h4, .standoutHeader {
  background: var(--bunny-pink) !important;
  color: var(--bunny-text) !important;
  font-family: 'VT323', monospace !important;
  border: 2px solid var(--bunny-border) !important;
  border-radius: 0 !important;
  padding: 4px 8px !important;
  text-shadow: none !important;
  letter-spacing: 1.5px;
}

/* =====================
   MESSAGE HEADINGS 
   ===================== */
.mes_text h1, .mes_text h2, .mes_text h3,
.mes_text h4, .mes_text h5, .mes_text h6 {
  font-family: 'VT323', monospace !important;
  text-shadow: none !important;
  letter-spacing: 1.5px;
}

.mes_text h1 {
  display: block !important;
