/* =====================
   LOADING SCREEN — Win95 pixel progress bar
   ===================== */

/* Dialog Frame */
#load-spinner {
  position: fixed !important;
  top: 50% !important;
  left: 50% !important;
  transform: translate(-50%, -50%) !important;
  width: 380px !important;
  height: 160px !important;
  max-width: 90vw !important;
  background: var(--bunny-cream) !important;
  border: 2px solid var(--bunny-rose) !important;
  border-radius: 0 !important;
  box-shadow: 4px 4px 0 var(--bunny-pink-dark), inset 1px 1px 0 rgba(21, 8, 16, 0.5) !important;
  /* Static progress bar track drawn on the dialog element via background */
  background-image: linear-gradient(var(--bunny-blush), var(--bunny-blush)) !important;
  background-size: calc(100% - 36px) 22px !important;
  background-position: 18px calc(100% - 16px) !important;
  background-repeat: no-repeat !important;
  filter: none !important;
  animation: none !important;
  overflow: hidden !important;
  font-family: 'VT323', monospace !important;
  z-index: 99999 !important;
  padding: 0 !important;
  margin: 0 !important;
}

/* Title bar + Body Text */
#load-spinner::before {
  content: "𝜗ৎ  System                       _  [ ]  X\A\ALoading F.A.Y.E. O.S..." !important;
  display: block !important;
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  bottom: 50px !important;
  padding: 3px 12px !important;
  white-space: pre !important;
  font-family: 'VT323', monospace !important;
  font-size: 16px !important;
  line-height: 22px !important;
  color: var(--bunny-text) !important;
  letter-spacing: 0.5px !important;
  text-shadow: 1px 1px 0 rgba(255,255,255,0.08) !important;
  overflow: hidden !important;
  box-sizing: border-box !important;
  /* Title bar band via background gradient */
  background-image: linear-gradient(
    to bottom,
    #b05070 0px, #6a2040 26px,
    var(--bunny-rose) 26px, var(--bunny-rose) 28px,
    transparent 28px
  ) !important;
}

/* Animated Progress Bar */
#load-spinner::after {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  top: auto !important;
  bottom: 16px !important;
  left: 18px !important;
  height: 22px !important;
  width: 0;
  max-width: calc(100% - 36px);
  border: 2px solid var(--bunny-rose) !important;
  border-radius: 0 !important;
  box-sizing: border-box !important;
  /* Pixel block pattern as background */
  background-color: var(--bunny-blush) !important;
  background-image: repeating-linear-gradient(
    to right,
    var(--bunny-rose) 0px,
    var(--bunny-rose) 12px,
    var(--bunny-blush) 12px,
    var(--bunny-blush) 16px
  ) !important;
  background-repeat: repeat !important;
  animation: bunny-load 2.5s ease-in-out infinite !important;
}

@keyframes bunny-load {
  0%, 5%   { width: 0; }
  50%      { width: 60%; }
  95%, 100%{ width: calc(100% - 36px); }
}

